/* 1. Сплошная граница коричневого цвета */
#par1 { border: 3px solid #8b4513; }

/* 2. Сплошная граница красного цвета слева и справа */
#par2 {
    border-left: 4px solid #d40000;
    border-right: 4px solid #d40000;
}

/* 3. Сверху сплошная розовая, слева, справа и снизу — пунктирная голубая */
#par3 {
    border-width: 3px 2px 2px 2px;
    border-style: solid dashed dashed dashed;
    border-color: #ff69b4 #00bfff #00bfff #00bfff;
}

/* 4. Граница оранжевого цвета толщиной 1 пиксель */
#par4 { border: 1px solid #ff8c00; }

/* 5. Сверху и снизу сплошная красная 2 px, слева и справа пунктирная серая */
#par5 {
    border-width: 2px;
    border-style: solid dashed;
    border-color: #d40000 #808080;
}

/* 6. Двойная граница цвета #1435AD */
#par6 { border: 5px double #1435ad; }

/* 7. Сверху пунктирная #FF8100 1 px, снизу сплошная #0B6124 2 px */
#par7 {
    border-top: 1px dashed #ff8100;
    border-bottom: 2px solid #0b6124;
}
